@group(0) @binding(1) var<storage, read> cxs: array<f32>;
@group(0) @binding(2) var<storage, read> cys: array<f32>;
@group(0) @binding(3) var<storage, read_write> times: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= params.width || id.y >= params.height) {
        return;
    }
    let cx = cxs[id.x];
    let cy = cys[id.y];
    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    loop {
        if (n >= params.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let next_zx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = next_zx;
        n = n + 1u;
