    if tokens.len() != 7 {
        return Err(format!("expected 7 values, found {}", tokens.len()));
    }
    let int = |s: &str, name: &str| -> Result<u32, String> {
        s.parse::<u32>().map_err(|e| format!("bad {name} '{s}': {e}"))
    };
    let num = |s: &str, name: &str| -> Result<f64, String> {
        s.parse::<f64>().map_err(|e| format!("bad {name} '{s}': {e}"))
    };
    let width = int(tokens[0], "width")?;
    let height = int(tokens[1], "height")?;
    let limit = int(tokens[2], "limit")?;
    if !(1..=1024).contains(&width) || !(1..=1024).contains(&height) {
        return Err("width and height must be between 1 and 1024".into());
    }
    if !(1..=1000).contains(&limit) {
        return Err("limit must be between 1 and 1000".into());
    }
    let job = Job {
        width,
        height,
        limit,
        x_min: num(tokens[3], "x_min")?,
        x_max: num(tokens[4], "x_max")?,
        y_min: num(tokens[5], "y_min")?,
        y_max: num(tokens[6], "y_max")?,
    };
