use std::sync::mpsc;

use bytemuck::{Pod, Zeroable};
use wgpu::util::DeviceExt;

/// One escape-time computation per invocation, workgroups tiled 16 x 16.
const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    _pad: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> cxs: array<f32>;
@group(0) @binding(2) var<storage, read> cys: array<f32>;
@group(0) @binding(3) var<storage, read_write> times: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= params.width || id.y >= params.height) {
        return;
    }
    let cx = cxs[id.x];
    let cy = cys[id.y];
    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    loop {
        if (n >= params.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let next_zx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = next_zx;
        n = n + 1u;
    }
    times[id.y * params.width + id.x] = n;
}
"#;

const TILE: u32 = 16;

#[repr(C)]
#[derive(Clone, Copy, Pod, Zeroable)]
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    _pad: u32,
}

struct Job {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse_job(text: &str) -> Result<Job, String> {
    let tokens: Vec<&str> = text.split_whitespace().collect();
    if tokens.len() != 7 {
        return Err(format!("expected 7 values, found {}", tokens.len()));
    }
    let int = |s: &str, name: &str| -> Result<u32, String> {
        s.parse::<u32>().map_err(|e| format!("bad {name} '{s}': {e}"))
    };
    let num = |s: &str, name: &str| -> Result<f64, String> {
        s.parse::<f64>().map_err(|e| format!("bad {name} '{s}': {e}"))
    };
    let width = int(tokens[0], "width")?;
    let height = int(tokens[1], "height")?;
    let limit = int(tokens[2], "limit")?;
    if !(1..=1024).contains(&width) || !(1..=1024).contains(&height) {
        return Err("width and height must be between 1 and 1024".into());
    }
    if !(1..=1000).contains(&limit) {
        return Err("limit must be between 1 and 1000".into());
    }
    let job = Job {
        width,
        height,
        limit,
        x_min: num(tokens[3], "x_min")?,
        x_max: num(tokens[4], "x_max")?,
        y_min: num(tokens[5], "y_min")?,
        y_max: num(tokens[6], "y_max")?,
    };
    if !(job.x_min < job.x_max) || !(job.y_min < job.y_max) {
        return Err("bounds must satisfy x_min < x_max and y_min < y_max".into());
    }
    if !job.x_min.is_finite()
        || !job.x_max.is_finite()
        || !job.y_min.is_finite()
        || !job.y_max.is_finite()
    {
        return Err("bounds must be finite".into());
    }
    Ok(job)
}

/// Point coordinates, computed in f64 on the host and narrowed once.
fn axis(min: f64, max: f64, count: u32) -> Vec<f32> {
    (0..count)
        .map(|i| (min + (f64::from(i) + 0.5) * (max - min) / f64::from(count)) as f32)
        .collect()
}

fn compute_escape_times(job: &Job) -> Result<Vec<u32>, String> {
    pollster::block_on(async {
        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
        let adapter = instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                power_preference: wgpu::PowerPreference::HighPerformance,
                ..Default::default()
            })
            .await
            .map_err(|e| format!("no GPU adapter: {e}"))?;
        let (device, queue) = adapter
            .request_device(&wgpu::DeviceDescriptor::default())
            .await
            .map_err(|e| format!("no GPU device: {e}"))?;

        let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("escape"),
            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
        });
        let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("escape"),
            layout: None,
            module: &module,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });
        let layout = pipeline.get_bind_group_layout(0);

        let params = Params {
            width: job.width,
            height: job.height,
            limit: job.limit,
            _pad: 0,
        };
        let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("params"),
            contents: bytemuck::bytes_of(&params),
            usage: wgpu::BufferUsages::UNIFORM,
        });
        let cx_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("cx"),
            contents: bytemuck::cast_slice(&axis(job.x_min, job.x_max, job.width)),
            usage: wgpu::BufferUsages::STORAGE,
        });
        let cy_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("cy"),
            contents: bytemuck::cast_slice(&axis(job.y_min, job.y_max, job.height)),
            usage: wgpu::BufferUsages::STORAGE,
        });

        let count = u64::from(job.width) * u64::from(job.height);
        let size = count * std::mem::size_of::<u32>() as u64;
        let out_buf = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("times"),
            size,
            usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
            mapped_at_creation: false,
        });
        let read_buf = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("readback"),
            size,
            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
            mapped_at_creation: false,
        });

        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("escape"),
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: cx_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: cy_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: out_buf.as_entire_binding(),
                },
            ],
        });

        let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
            label: Some("escape"),
        });
        {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("escape"),
                ..Default::default()
            });
            pass.set_pipeline(&pipeline);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(job.width.div_ceil(TILE), job.height.div_ceil(TILE), 1);
        }
        encoder.copy_buffer_to_buffer(&out_buf, 0, &read_buf, 0, size);
        queue.submit(Some(encoder.finish()));

        let slice = read_buf.slice(..);
        let (tx, rx) = mpsc::channel();
        slice.map_async(wgpu::MapMode::Read, move |result| {
            let _ = tx.send(result);
        });
        device
            .poll(wgpu::PollType::wait_indefinitely())
            .map_err(|e| format!("GPU poll failed: {e}"))?;
        rx.recv()
            .map_err(|e| format!("map callback lost: {e}"))?
            .map_err(|e| format!("readback failed: {e}"))?;

        let times = {
            let data = slice.get_mapped_range();
            bytemuck::cast_slice::<u8, u32>(&data).to_vec()
        };
        read_buf.unmap();
        Ok(times)
    })
}

fn summarize(times: &[u32], limit: u32) -> String {
    let mut inside = 0u64;
    let mut bins = [0u64; 8];
    let mut escaped = 0u64;
    let mut sum = 0u64;
    for &n in times {
        if n >= limit {
            inside += 1;
        } else {
            escaped += 1;
            sum += u64::from(n);
            let bin = (8 * u64::from(n) / u64::from(limit)) as usize;
            bins[bin] += 1;
        }
    }
    let mean = if escaped == 0 {
        0.0
    } else {
        sum as f64 / escaped as f64
    };

    let mut out = format!("INSIDE {inside}\n");
    for (b, count) in bins.iter().enumerate() {
        out.push_str(&format!("BIN {b} {count}\n"));
    }
    out.push_str(&format!("MEAN {mean:.3}\n"));
    out
}

fn run() -> Result<(), Box<dyn Error>> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: escape_times <input-file>")?;
    let text = fs::read_to_string(&path).map_err(|e| format!("cannot read '{path}': {e}"))?;
    let job = parse_job(&text)?;
    let times = compute_escape_times(&job)?;
    print!("{}", summarize(&times, job.limit));
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

